test("c1: an all upper-case title comes out lower case", () => {
  assert.equal(slugify("HELLO"), "hello");
});

test("c1: mixed-case letters come out lower case", () => {
  assert.equal(slugify("HeLLoWorld"), "helloworld");
});

test("c1: lower-case letters are left as they are", () => {
  assert.equal(slugify("hello"), "hello");
});

test("c2: a single space between words becomes a dash", () => {
  assert.equal(slugify("hello world"), "hello-world");
});

test("c2: a run of several spaces becomes a single dash", () => {
  assert.equal(slugify("hello     world"), "hello-world");
});

test("c2: every run of spaces between words becomes one dash", () => {
  assert.equal(slugify("hello   big world  again"), "hello-big-world-again");
});

test("c3: punctuation is removed", () => {
  assert.equal(slugify("hello,world!"), "helloworld");
});

test("c3: varied punctuation marks are all removed", () => {
  assert.equal(slugify("what's.up?(yes):no;\"ok\""), "whatsupyesnook");
});

test("c3: accented letters are removed", () => {
  assert.equal(slugify("héllowörld"), "hllowrld");
});

test("c3: punctuation and accented letters together are removed", () => {
  assert.equal(slugify("café,señor!"), "cafseor");
});

