test("c1: combined hours and minutes are summed in seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number is that many seconds", () => {
  assert.equal(parseDuration("90"), 90);
  assert.equal(parseDuration("45"), 45);
});

test("c3: a part can be a decimal", () => {
  assert.equal(parseDuration("1.5h"), 5400);
  assert.equal(parseDuration("2.5m"), 150);
});

test("c4: unit letters can be upper case", () => {
  assert.equal(parseDuration("1H30M"), 5400);
  assert.equal(parseDuration("2H"), 7200);
});

test("c5: units written smaller before larger are null", () => {
  // The same parts in the right order parse, so the null below comes from the order.
  assert.notEqual(parseDuration("1h30m"), null);
  assert.equal(parseDuration("30m1h"), null);
});

test("c6: an unknown unit is null", () => {
  // The same number with a known unit parses, so the null below comes from the unit.
  assert.notEqual(parseDuration("1h"), null);
  assert.equal(parseDuration("1x"), null);
});

test('c1: "1h30m" returns 5400', () => {
  assert.strictEqual(parseDuration("1h30m"), 5400);
});

test('c2: a bare number "90" is returned as 90 seconds', () => {
  assert.strictEqual(parseDuration("90"), 90);
});

test('c3: a decimal part is accepted, "1.5h" returns 5400', () => {
  assert.strictEqual(parseDuration("1.5h"), 5400);
});

test('c4: upper-case unit letters are accepted, "1H30M" returns 5400', () => {
  assert.strictEqual(parseDuration("1H30M"), 5400);
});

test('c5: smaller unit before larger, "30m1h", returns null', () => {
  // Control: the same parts in larger-to-smaller order must parse, so the
  // null below is caused by the ordering and not by a parser that rejects everything.
  assert.notStrictEqual(parseDuration("1h30m"), null);
  assert.strictEqual(parseDuration("30m1h"), null);
});

test('c6: an unknown unit, "1x", returns null', () => {
  // Control: the same number with a known unit must parse, so the null below
  // is caused by the unit and not by a parser that rejects everything.
  assert.notStrictEqual(parseDuration("1h"), null);
  assert.strictEqual(parseDuration("1x"), null);
});

test("c1: hours and minutes combine, so \"1h30m\" is 5400 seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number with no unit, \"90\", is that many seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("c3: a decimal part is accepted, so \"1.5h\" is 5400 seconds", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("c4: upper-case unit letters are accepted, so \"1H30M\" is 5400 seconds", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("c5: a smaller unit before a larger one, \"30m1h\", is null", () => {
  assert.equal(parseDuration("30m1h"), null);
});

test("c6: an unknown unit, \"1x\", is null", () => {
  assert.equal(parseDuration("1x"), null);
});
